:root {
  --orange: #FF7A3D;
  --ink: #050505;
  --text: #F1F1F1;
  --mute: #999999;
  --mute-2: #666666;
  --line: #2F2F2F;
  --surface: rgba(255, 255, 255, 0.04);
  --surface-2: rgba(255, 255, 255, 0.07);
  --font-cn: "Noto Sans SC", "Microsoft YaHei", "PingFang SC", "Noto Sans", system-ui, sans-serif;
  --font-mono: "Consolas", "Courier New", monospace;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  height: 100%;
  background: transparent;
}

body {
  font-family: var(--font-cn);
  color: var(--text);
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

.widget {
  display: flex;
  flex-direction: column;
  height: 100vh;
  background: var(--ink);
  border: 1px solid var(--line);
}

/* ---------- Top bar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  background: var(--ink);
  border-bottom: 2px solid var(--orange);
}

.brand {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.brand-cn {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.brand-en {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  color: var(--orange);
  letter-spacing: 1px;
}

.topbar-actions {
  display: flex;
  gap: 6px;
}

.icon-btn {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  color: var(--mute);
  background: transparent;
  border: 1px solid var(--line);
  padding: 3px 8px;
  cursor: pointer;
}

.icon-btn:hover {
  color: var(--ink);
  background: var(--orange);
  border-color: var(--orange);
}

/* ---------- Meta row ---------- */
.meta-row {
  display: flex;
  gap: 14px;
  padding: 7px 12px;
  border-bottom: 1px solid var(--line);
}

.meta-cell {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--mute-2);
  letter-spacing: 0.3px;
}

/* ---------- Banner ---------- */
.banner {
  font-family: var(--font-mono);
  font-size: 10px;
  padding: 6px 12px;
  background: var(--surface-2);
  color: var(--orange);
  border-bottom: 1px solid var(--line);
}

.banner.error {
  color: var(--orange);
}

.hidden {
  display: none;
}

/* ---------- Tabs ---------- */
.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  padding: 8px 12px 0;
  border-bottom: 1px solid var(--line);
}

.tab {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.4px;
  color: var(--mute);
  background: transparent;
  border: none;
  border-bottom: 3px solid transparent;
  padding: 5px 9px 7px;
  cursor: pointer;
}

.tab:hover {
  color: var(--text);
}

.tab.active {
  color: var(--text);
  border-bottom-color: var(--orange);
}

/* ---------- Content ---------- */
.content {
  flex: 1;
  overflow-y: auto;
  padding: 10px 12px 14px;
}

.placeholder {
  font-size: 12px;
  color: var(--mute-2);
  padding: 24px 4px;
  text-align: center;
}

/* Brief view */
.brief-summary {
  font-size: 12.5px;
  line-height: 1.55;
  color: var(--text);
  padding-bottom: 10px;
  margin-bottom: 10px;
  border-bottom: 1px solid var(--line);
}

.brief-bullet {
  padding: 8px 10px;
  margin-bottom: 8px;
  background: var(--surface);
  border-top: 3px solid var(--orange);
}

.brief-bullet .topic {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  color: var(--orange);
  letter-spacing: 0.5px;
  display: block;
  margin-bottom: 3px;
}

.brief-bullet .point {
  font-size: 12px;
  line-height: 1.45;
  color: var(--text);
}

/* Item card */
.card {
  display: block;
  padding: 9px 10px;
  margin-bottom: 8px;
  background: var(--surface);
  border-top: 3px solid var(--orange);
  cursor: pointer;
  text-decoration: none;
}

.card:hover {
  background: var(--surface-2);
}

.card .rank {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  color: var(--mute-2);
}

.card .title {
  font-size: 12.5px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--text);
  margin: 2px 0 4px;
}

.card .summary {
  font-size: 11px;
  line-height: 1.4;
  color: var(--mute);
  margin-bottom: 5px;
}

.card .tip {
  font-size: 10.5px;
  line-height: 1.4;
  color: var(--orange);
  padding: 5px 7px;
  margin-bottom: 5px;
  border-left: 3px solid var(--orange);
  background: var(--surface-2);
}

.card .card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.card .card-meta span {
  font-family: var(--font-mono);
  font-size: 9.5px;
  color: var(--mute-2);
  letter-spacing: 0.3px;
}

.card .pill {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  color: var(--ink);
  background: var(--orange);
  padding: 1px 5px;
  letter-spacing: 0.3px;
}

.empty {
  font-size: 11.5px;
  color: var(--mute-2);
  padding: 18px 4px;
  text-align: center;
}

/* ---------- Status bar ---------- */
.statusbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 12px;
  border-top: 1px solid var(--line);
}

.status-left,
.status-right {
  font-family: var(--font-mono);
  font-size: 9.5px;
  color: var(--mute-2);
  letter-spacing: 0.4px;
}

/* ---------- Scrollbar ---------- */
.content::-webkit-scrollbar {
  width: 8px;
}

.content::-webkit-scrollbar-track {
  background: transparent;
}

.content::-webkit-scrollbar-thumb {
  background: var(--line);
}

.content::-webkit-scrollbar-thumb:hover {
  background: var(--mute-2);
}

"use strict";

const TAURI = window.__TAURI__ || null;

const SECTIONS = [
  { id: "brief", cn: "今日要点", en: "BRIEF" },
  { id: "local", cn: "本地热点", en: "LOCAL" },
  { id: "products", cn: "消费电子", en: "GADGETS" },
  { id: "marketing", cn: "营销", en: "CAMPAIGN" },
  { id: "reddit", cn: "Reddit", en: "REDDIT" },
  { id: "culture", cn: "网感", en: "CULTURE" },
  { id: "viral", cn: "Viral", en: "VIRAL" },
];

const state = {
  digest: null,
  section: "brief",
  config: { defaultSection: "brief", itemsPerSection: 8, refreshIntervalMinutes: 60 },
  loading: false,
};

let refreshTimer = null;

const els = {
  date: document.getElementById("meta-date"),
  next: document.getElementById("meta-next"),
  banner: document.getElementById("banner"),
  tabs: document.getElementById("tabs"),
  content: document.getElementById("content"),
  statusRight: document.getElementById("status-right"),
  btnRefresh: document.getElementById("btn-refresh"),
  btnHide: document.getElementById("btn-hide"),
};

/* ---------- helpers ---------- */

function esc(value) {
  return String(value == null ? "" : value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function formatAge(item) {
  const age = item && item.ageHours;
  if (age == null) return "未知";
  if (age < 1) return "1h 内";
  return Math.round(age) + "h 前";
}

function getItems(digest, sectionId) {
  if (!digest) return [];
  switch (sectionId) {
    case "local":
      return [...(digest.social?.us || []), ...(digest.social?.ca || [])];
    case "products":
      return digest.products || [];
    case "marketing":
      return digest.marketing || [];
    case "reddit":
      return digest.socialTrends?.reddit || [];
    case "culture":
      return digest.cultureSignals || [];
    case "viral":
      return digest.viralStories || [];
    default:
      return [];
  }
}

function isSafeUrl(url) {
  return typeof url === "string" && /^https?:\/\//i.test(url);
}

async function openLink(url) {
  if (!isSafeUrl(url)) return;
  try {
    if (TAURI?.opener?.openUrl) {
      await TAURI.opener.openUrl(url);
    } else {
      window.open(url, "_blank", "noopener");
    }
  } catch (err) {
    console.error("openLink failed", err);
  }
}

/* ---------- rendering ---------- */

function renderTabs() {
  els.tabs.innerHTML = SECTIONS.map(
    (s) =>
      `<button class="tab${s.id === state.section ? " active" : ""}" data-section="${s.id}">${esc(
        s.cn,
      )} · ${esc(s.en)}</button>`,
  ).join("");
}

function cardHtml(item, rank) {
  const title = item.zhTitle || item.title || "未命名信号";
  const summary = item.zhSummary || item.summary || "";
  const label = item.priorityLabel || item.priority || "";
  const parts = [];
  parts.push(`<a class="card" href="${esc(item.link || "#")}" data-link="${esc(item.link || "")}">`);
  parts.push(`<span class="rank">${String(rank).padStart(2, "0")}</span>`);
  parts.push(`<div class="title">${esc(title)}</div>`);
  if (summary) parts.push(`<div class="summary">${esc(summary)}</div>`);
  if (item.marketingTip) parts.push(`<div class="tip">营销 · ${esc(item.marketingTip)}</div>`);
  parts.push('<div class="card-meta">');
  if (item.source) parts.push(`<span>${esc(item.source)}</span>`);
  parts.push(`<span>${esc(formatAge(item))}</span>`);
  if (label) parts.push(`<span class="pill">${esc(label)}</span>`);
  parts.push("</div></a>");
  return parts.join("");
}

function renderBrief(digest) {
  const ai = digest?.ai || {};
  const blocks = [];
  if (ai.executiveSummary) {
    blocks.push(`<div class="brief-summary">${esc(ai.executiveSummary)}</div>`);
  }
  const bullets = ai.executiveBullets || [];
  for (const b of bullets) {
    blocks.push(
      `<div class="brief-bullet"><span class="topic">${esc(b.topic || "")}</span><span class="point">${esc(
        b.point || "",
      )}</span></div>`,
    );
  }
  if (!blocks.length) {
    return '<div class="empty">暂无编辑摘要。可切换上方分区查看具体条目。</div>';
  }
  return blocks.join("");
}

function renderContent() {
  if (!state.digest) {
    els.content.innerHTML = '<div class="placeholder">正在读取北美日报…</div>';
    return;
  }
  if (state.section === "brief") {
    els.content.innerHTML = renderBrief(state.digest);
    els.content.scrollTop = 0;
    return;
  }
  const items = getItems(state.digest, state.section).slice(0, state.config.itemsPerSection);
  if (!items.length) {
    els.content.innerHTML = '<div class="empty">近 24h 暂无可用内容。</div>';
    return;
  }
  els.content.innerHTML = items.map((item, i) => cardHtml(item, i + 1)).join("");
  els.content.scrollTop = 0;
}

function renderMeta(payload) {
  const digest = state.digest;
  els.date.textContent = "本期 " + (digest?.archiveDate || "今日");
  els.next.textContent = "下次 " + (digest?.nextRefreshBeijing || "08:00 BJT");

  els.banner.classList.add("hidden");
  els.banner.classList.remove("error");
  if (payload?.stale) {
    els.banner.classList.remove("hidden");
    els.banner.classList.add("error");
    els.banner.textContent =
      "数据可能过期 · 缓存于 " + (payload.cachedAt ? formatClock(payload.cachedAt) : "未知") + " · 内网不可达";
  } else if (digest && digest.ai && digest.ai.status && digest.ai.status !== "ready") {
    els.banner.classList.remove("hidden");
    els.banner.textContent = "AI 整理未就绪 · 显示原始内容";
  }

  els.statusRight.textContent = payload?.stale ? "OFFLINE / CACHE" : "LIVE";
}

function formatClock(iso) {
  try {
    const d = new Date(iso);
    const p = (n) => String(n).padStart(2, "0");
    return `${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
  } catch {
    return "未知";
  }
}

/* ---------- data ---------- */

async function loadDigest(force) {
  if (state.loading) return;
  state.loading = true;
  els.btnRefresh.textContent = "…";
  try {
    let payload;
    if (TAURI?.core?.invoke) {
      payload = await TAURI.core.invoke("load_digest", { force: Boolean(force) });
    } else {
      payload = await devFetch();
    }
    if (payload?.config) state.config = { ...state.config, ...payload.config };
    if (payload?.data) {
      state.digest = payload.data;
      renderContent();
    } else if (!state.digest) {
      els.content.innerHTML =
        '<div class="placeholder">内网接口不可达，且无本地缓存。<br/>稍后点击“刷新”重试。</div>';
    }
    renderMeta(payload);
  } catch (err) {
    console.error("loadDigest failed", err);
    if (!state.digest) {
      els.content.innerHTML = '<div class="placeholder">加载失败：' + esc(String(err)) + "</div>";
    }
  } finally {
    state.loading = false;
    els.btnRefresh.textContent = "刷新";
  }
}

// Best-effort fallback for previewing in a plain browser (no Tauri runtime).
async function devFetch() {
  const base = "http://172.16.199.56:5050";
  const res = await fetch(base + "/api/digest?ai=1");
  const data = await res.json();
  return { ok: true, stale: false, cachedAt: null, data, config: state.config };
}

/* ---------- events ---------- */

function scheduleRefresh() {
  if (refreshTimer) clearInterval(refreshTimer);
  const minutes = Math.max(5, Number(state.config.refreshIntervalMinutes) || 60);
  refreshTimer = setInterval(() => loadDigest(false), minutes * 60 * 1000);
}

function bindEvents() {
  els.tabs.addEventListener("click", (e) => {
    const btn = e.target.closest(".tab");
    if (!btn) return;
    state.section = btn.dataset.section;
    renderTabs();
    renderContent();
  });

  els.content.addEventListener("click", (e) => {
    const card = e.target.closest(".card");
    if (!card) return;
    e.preventDefault();
    openLink(card.dataset.link);
  });

  els.btnRefresh.addEventListener("click", () => loadDigest(true));

  els.btnHide.addEventListener("click", async () => {
    try {
      if (TAURI?.window?.getCurrentWindow) {
        await TAURI.window.getCurrentWindow().hide();
      }
    } catch (err) {
      console.error("hide failed", err);
    }
  });

  if (TAURI?.event?.listen) {
    TAURI.event.listen("refresh-digest", () => loadDigest(true));
  }
}

/* ---------- init ---------- */

async function init() {
  state.section = state.config.defaultSection || "brief";
  renderTabs();
  bindEvents();
  await loadDigest(false);
  if (state.config.defaultSection && state.config.defaultSection !== state.section) {
    state.section = state.config.defaultSection;
    renderTabs();
    renderContent();
  }
  scheduleRefresh();
}

document.addEventListener("DOMContentLoaded", init);

{
  "name": "na-trend-widget",
  "version": "0.1.0",
  "private": true,
  "description": "北美趋势日报桌面挂件 (Tauri)",
