use serde::Serialize;
use serde_json::Value;
use std::fs;
use std::path::PathBuf;
use std::time::Duration;
use tauri::{
    menu::{Menu, MenuItem},
    tray::{MouseButton, MouseButtonState, TrayIconBuilder, TrayIconEvent},
    AppHandle, Emitter, Manager, WindowEvent,
};
use tauri_plugin_autostart::ManagerExt;

const DEFAULT_CONFIG: &str = include_str!("../../config.json");

#[derive(Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct AppConfig {
    api_base_url: String,
    refresh_interval_minutes: u64,
    default_section: String,
    items_per_section: u64,
}

fn parse_config(raw: &str) -> AppConfig {
    let v: Value = serde_json::from_str(raw).unwrap_or(Value::Null);
    AppConfig {
        api_base_url: v
            .get("apiBaseUrl")
            .and_then(|x| x.as_str())
            .unwrap_or("http://172.16.199.56:5050")
            .to_string(),
        refresh_interval_minutes: v
            .get("refreshIntervalMinutes")
            .and_then(|x| x.as_u64())
            .unwrap_or(60),
        default_section: v
            .get("defaultSection")
            .and_then(|x| x.as_str())
            .unwrap_or("brief")
            .to_string(),
        items_per_section: v
            .get("itemsPerSection")
            .and_then(|x| x.as_u64())
            .unwrap_or(8),
    }
}

/// Load config with override priority: app config dir > bundled resource > compile-time default.
fn load_config(app: &AppHandle) -> AppConfig {
    if let Ok(dir) = app.path().app_config_dir() {
        if let Ok(raw) = fs::read_to_string(dir.join("config.json")) {
            return parse_config(&raw);
        }
    }
    if let Ok(dir) = app.path().resource_dir() {
        if let Ok(raw) = fs::read_to_string(dir.join("config.json")) {
            return parse_config(&raw);
        }
    }
    parse_config(DEFAULT_CONFIG)
}

fn cache_path(app: &AppHandle) -> Option<PathBuf> {
    let dir = app.path().app_data_dir().ok()?;
    let _ = fs::create_dir_all(&dir);
    Some(dir.join("last_digest.json"))
}

fn save_cache(app: &AppHandle, data: &Value) {
    if let Some(p) = cache_path(app) {
        let wrapper = serde_json::json!({
            "cachedAt": chrono::Local::now().to_rfc3339(),
            "data": data,
        });
        let _ = fs::write(p, wrapper.to_string());
    }
}

fn read_cache(app: &AppHandle) -> Option<(Value, String)> {
    let raw = fs::read_to_string(cache_path(app)?).ok()?;
    let v: Value = serde_json::from_str(&raw).ok()?;
    let data = v.get("data")?.clone();
    let cached_at = v
        .get("cachedAt")
        .and_then(|x| x.as_str())
        .unwrap_or("")
        .to_string();
    Some((data, cached_at))
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct LoadResult {
    ok: bool,
    stale: bool,
    cached_at: Option<String>,
    error: Option<String>,
    data: Option<Value>,
    config: AppConfig,
}

async fn fetch_digest(base: &str) -> Result<Value, String> {
    let url = format!("{}/api/digest?ai=1", base.trim_end_matches('/'));
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(20))
        .build()
        .map_err(|e| e.to_string())?;
    let resp = client.get(&url).send().await.map_err(|e| e.to_string())?;
    if !resp.status().is_success() {
        return Err(format!("HTTP {}", resp.status()));
    }
    resp.json::<Value>().await.map_err(|e| e.to_string())
}

#[tauri::command]
async fn load_digest(app: AppHandle, _force: bool) -> LoadResult {
    let config = load_config(&app);
    match fetch_digest(&config.api_base_url).await {
        Ok(data) => {
            save_cache(&app, &data);
            LoadResult {
                ok: true,
                stale: false,
                cached_at: None,
                error: None,
                data: Some(data),
                config,
            }
        }
        Err(e) => match read_cache(&app) {
            Some((data, cached_at)) => LoadResult {
                ok: false,
                stale: true,
                cached_at: Some(cached_at),
                error: Some(e),
                data: Some(data),
                config,
            },
            None => LoadResult {
                ok: false,
                stale: false,
                cached_at: None,
                error: Some(e),
                data: None,
                config,
            },
        },
    }
}

fn show_widget(app: &AppHandle) {
    if let Some(win) = app.get_webview_window("main") {
        let _ = win.show();
        let _ = win.set_focus();
    }
}

fn toggle_widget(app: &AppHandle) {
    if let Some(win) = app.get_webview_window("main") {
        if win.is_visible().unwrap_or(false) {
            let _ = win.hide();
        } else {
            let _ = win.show();
            let _ = win.set_focus();
        }
    }
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_single_instance::init(|app, _args, _cwd| {
            show_widget(app);
        }))
        .plugin(tauri_plugin_window_state::Builder::new().build())
        .plugin(tauri_plugin_autostart::Builder::new().build())
        .plugin(tauri_plugin_opener::init())
        .invoke_handler(tauri::generate_handler![load_digest])
        .setup(|app| {
            if cfg!(debug_assertions) {
                app.handle().plugin(
                    tauri_plugin_log::Builder::default()
                        .level(log::LevelFilter::Info)
                        .build(),
                )?;
            }

            let toggle_i = MenuItem::with_id(app, "toggle", "显示 / 隐藏挂件", true, None::<&str>)?;
            let refresh_i = MenuItem::with_id(app, "refresh", "立即刷新", true, None::<&str>)?;
            let autostart_i = MenuItem::with_id(app, "autostart", "开机自启", true, None::<&str>)?;
            let quit_i = MenuItem::with_id(app, "quit", "退出", true, None::<&str>)?;
            let menu = Menu::with_items(app, &[&toggle_i, &refresh_i, &autostart_i, &quit_i])?;

            let _tray = TrayIconBuilder::with_id("main-tray")
                .icon(app.default_window_icon().unwrap().clone())
                .tooltip("北美趋势日报")
                .menu(&menu)
                .show_menu_on_left_click(false)
                .on_menu_event(|app, event| match event.id.as_ref() {
                    "toggle" => toggle_widget(app),
                    "refresh" => {
                        let _ = app.emit("refresh-digest", ());
                    }
                    "autostart" => {
                        let mgr = app.autolaunch();
                        if mgr.is_enabled().unwrap_or(false) {
                            let _ = mgr.disable();
                        } else {
                            let _ = mgr.enable();
                        }
                    }
                    "quit" => app.exit(0),
                    _ => {}
                })
                .on_tray_icon_event(|tray, event| {
                    if let TrayIconEvent::Click {
                        button: MouseButton::Left,
                        button_state: MouseButtonState::Up,
                        ..
                    } = event
                    {
                        toggle_widget(tray.app_handle());
                    }
                })
                .build(app)?;

            Ok(())
        })
        .on_window_event(|window, event| {
            if let WindowEvent::CloseRequested { api, .. } = event {
                let _ = window.hide();
                api.prevent_close();
            }
        })
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

