function monogramFor(source) {
  const s = String(source || "?").trim();
  const letter = (s.charAt(0) || "?").toUpperCase();
  let h = 0;
  for (let i = 0; i < s.length; i += 1) {
    h = (h * 31 + s.charCodeAt(i)) >>> 0;
  }
  const hue = h % 360;
  const bg = `hsl(${hue}, 52%, 46%)`;
  return { letter, bg };
}

function cardHtml(item) {
  const title = item.zhTitle || item.title || "未命名信号";
  const summary = item.zhSummary || item.summary || "";
  const label = item.priorityLabel || item.priority || "";
  const mg = monogramFor(item.source);
  const parts = [];
  parts.push(`<a class="card" href="${esc(item.link || "#")}" data-link="${esc(item.link || "")}">`);
  parts.push(`<span class="mono" style="background:${mg.bg}">${esc(mg.letter)}</span>`);
  parts.push('<div class="card-body">');
  parts.push(`<div class="title">${esc(title)}</div>`);
  if (summary) parts.push(`<div class="summary">${esc(summary)}</div>`);
  if (item.marketingTip) parts.push(`<div class="tip">营销 · ${esc(item.marketingTip)}</div>`);
  parts.push('<div class="card-meta">');
  if (item.source) parts.push(`<span class="src">${esc(item.source)}</span>`);
  parts.push(`<span class="age">${esc(formatAge(item))}</span>`);
  if (label) parts.push(`<span class="pill">${esc(label)}</span>`);
  parts.push("</div></div></a>");
