/* ---------- settings ---------- */

function openSettings() {
  if (!els.settings) return;
  els.cfgApi.value = state.config.apiBaseUrl || "";
  els.cfgInterval.value = state.config.refreshIntervalMinutes || 60;
  els.cfgMsg.textContent = "";
  els.settings.classList.remove("hidden");
  els.cfgApi.focus();
}

function closeSettings() {
  if (els.settings) els.settings.classList.add("hidden");
}

async function saveSettings() {
  const apiBaseUrl = (els.cfgApi.value || "").trim().replace(/\/$/, "");
  const interval = Number(els.cfgInterval.value);
  if (apiBaseUrl && !/^https?:\/\//i.test(apiBaseUrl)) {
    els.cfgMsg.textContent = "地址需以 http:// 或 https:// 开头";
    return;
  }
  if (interval && interval < 5) {
    els.cfgMsg.textContent = "刷新间隔不能小于 5 分钟";
    return;
  }
  try {
    if (TAURI?.core?.invoke) {
      const saved = await TAURI.core.invoke("save_config", {
        apiBaseUrl: apiBaseUrl || null,
        refreshIntervalMinutes: interval || null,
      });
      if (saved) state.config = { ...state.config, ...saved };
    } else {
      state.config = {
        ...state.config,
        apiBaseUrl: apiBaseUrl || state.config.apiBaseUrl,
        refreshIntervalMinutes: interval || state.config.refreshIntervalMinutes,
      };
    }
    closeSettings();
    showToast("已保存设置");
    scheduleRefresh();
    await loadDigest(true);
  } catch (err) {
    console.error("save_config failed", err);
    els.cfgMsg.textContent = "保存失败：" + String(err);
  }
}

