  font-family: var(--font-ui);
  font-size: 10px;
  color: var(--mute);
  letter-spacing: var(--label-spacing);
}

.settings-field input {
  font-family: var(--font-ui);
  font-size: 12px;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--edge);
  border-radius: var(--radius-sm);
  padding: 7px 9px;
  user-select: text;
}

.settings-field input:focus {
  outline: none;
  border-color: var(--accent);
}

.settings-msg {
  font-family: var(--font-ui);
  font-size: 10px;
  color: var(--accent-2);
  min-height: 12px;
}

.settings-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--s2);
}

.settings-btn {
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 700;
  color: var(--mute);
  background: var(--surface-2);
  border: none;
  border-radius: var(--radius-sm);
  padding: 7px 14px;
  cursor: pointer;
  transition: opacity 0.14s ease, color 0.14s ease;
}

.settings-btn:hover {
  color: var(--text);
}

.settings-btn.primary {
  color: var(--on-accent);
  background: var(--accent);
}

.settings-btn.primary:hover {
  opacity: 0.85;
}

/* ---------- Toast ---------- */

"windowEffects": {
  "effects": ["acrylic"],
  "radius": 12
}

input.new_string:
"windowEffects": {
  "effects": ["blur"],
  "radius": 12
}
